from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base TRMM kernel: mirrors the original PolyBench implementation.
@proc
def kernel_trmm_base(
    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Original algorithm:
    # for i in 0..m-1
    #   for j in 0..n-1
    #     for k in i+1..m-1
    #       B[i,j] += A[k,i] * B[k,j]
    #     B[i,j] = alpha * B[i,j]
    for i in seq(0, m):
        for j in seq(0, n):
            for k in seq(i + 1, m):
                B[i, j] += A[k, i] * B[k, j]
            B[i, j] = alpha * B[i, j]


# Optimization schedule.
kernel_trmm_opt = kernel_trmm_base

# 1. Fission the inner j-loop into:
#    (a) accumulation over k
#    (b) scaling by alpha
j_loop = kernel_trmm_opt.find_loop("j")
kernel_trmm_opt = fission(kernel_trmm_opt, j_loop.body()[0].after(), n_lifts=1)

# After fission, for each i we have:
#   for j:        # j #0
#       for k: ...
#   for j:        # j #1
#       B[i, j] = alpha * B[i, j]

