#    spatial locality on B: i -> k -> j instead of i -> j -> k.
j0 = kernel_trmm_opt.find_loop("j #0")
kernel_trmm_opt = reorder_loops(kernel_trmm_opt, j0)

# 3. Hoist A[k, i] out of the innermost j-loop so that we load it
#    only once per (i, k) pair.
a_ki_exprs = [kernel_trmm_opt.find("A[k, i]")]
kernel_trmm_opt = bind_expr(kernel_trmm_opt, a_ki_exprs, "a_ki")

# 4. Tile the j-dimension in both nests to improve cache locality for
#    wide matrices. The tile size can be tuned per architecture.
J_TILE = 32

# Tile the j-loop that performs the accumulation.
j_accum = kernel_trmm_opt.find_loop("j #0")
kernel_trmm_opt = divide_loop(kernel_trmm_opt, j_accum, J_TILE, ["jo", "ji"], tail="guard")

# Tile the j-loop that performs the final scaling.
j_scale = kernel_trmm_opt.find_loop("j #1")
kernel_trmm_opt = divide_loop(kernel_trmm_opt, j_scale, J_TILE, ["jo_s", "ji_s"], tail="guard")

