    m: size,
    n: size,
    alpha: DATA_TYPE,
    A: DATA_TYPE[m, m] @ DRAM,
    B: DATA_TYPE[m, n] @ DRAM,
):
    # Compute B := alpha * (L^T * B), where L is a unit lower-triangular
    # matrix stored in A. We restructure the computation so that the
    # innermost loop iterates over j, giving stride-1 access to both
    # B[i, j] and B[k, j].
    for i in seq(0, m):
        # Rank-1 updates: for each k > i, add A[k, i] * B[k, :] into row i.
        # This is algebraically identical to the original PolyBench kernel:
        #   for j:
        #     for k in i+1..m-1:
        #       B[i,j] += A[k,i] * B[k,j]
        for k in seq(i + 1, m):
            for j in seq(0, n):
                B[i, j] += A[k, i] * B[k, j]
        # Scale the updated row by alpha.
        for j in seq(0, n):
            B[i, j] = alpha * B[i, j]


